using PdfPrototype;
using System.IO;
var folder=Path.GetFullPath(args[0]);Directory.CreateDirectory(folder);var rows=new List<object>();int failures=0;
void Check(string name,Action action){try{action();rows.Add(new{name,status="pass"});}catch(Exception e){failures++;rows.Add(new{name,status="fail",error=e.ToString()});}}
void Assert(bool b,string m){if(!b)throw new Exception(m);}
Region Region(string id,int page=0)=>new(){Id=id,Page=page,SourceHash=new string('a',64),Objects=[id[0]],OriginalLines=["abc"],Advances=Enumerable.Repeat(6.0,95).ToArray()};
DocumentSession Session(){var s=new DocumentSession{Source="source.pdf",SourceHash=new string('a',64)};s.Register(new[]{Region("a"),Region("b"),Region("c",1)});return s;}
Check("chronological-undo-redo-and-branch",()=>{var s=Session();s.Change("0:a","first",2);s.Change("0:b","second",3);s.Change("1:c","third",4);Assert(s.MoveHistory(false)!.Key=="1:c","C undo");Assert(s.MoveHistory(false)!.Key=="0:b","B undo");Assert(s.MoveHistory(false)!.Key=="0:a","A undo");for(int i=0;i<3;i++)s.MoveHistory(true);Assert(s.Regions["1:c"].Text=="third","Redo");s.MoveHistory(false);s.Change("0:a","new branch",5);Assert(!s.CanRedo,"Stale redo");});
Check("selection-and-unchanged-restoration-no-history",()=>{var s=Session();s.Regions["0:a"].Caret=2;s.Register(new[]{Region("a")});s.Change("0:a","abc",2);Assert(s.History.Count==0&&s.Revision==0,"Spurious entry");});
Check("foreign-session-response-and-stale-revision-refused",()=>{var a=Session();var b=Session();a.Change("0:a","draft",0);b.Change("0:a","other",0);Assert(a.Revision==b.Revision&&!b.MatchesResponse(a,a.Revision,a.SourceHash),"Foreign equal-revision response accepted");Assert(a.MatchesResponse(a,a.Revision,a.SourceHash),"Current response refused");long old=a.Revision;a.Change("0:b","later",0);Assert(!a.MatchesResponse(a,old,a.SourceHash)&&!a.MatchesResponse(a,a.Revision,new string('b',64)),"Stale revision/hash accepted");});
Check("entry-bound-and-evicted-count",()=>{var s=Session();for(int i=0;i<2010;i++)s.Change("0:a","edit-"+i,0);Assert(s.History.Count==2000&&s.EvictedHistory==10,"Entry bound");for(int i=0;i<2000;i++)s.MoveHistory(false);Assert(!s.CanUndo&&s.Regions["0:a"].Text=="edit-9","Evicted boundary incorrect");});
Check("history-character-bound-retains-entire-draft",()=>{var s=Session();string text=new('x',3_000_000);s.Change("0:a",text,0);Assert(s.History.Count==0&&s.Regions["0:a"].Text==text,"Large draft truncated");});
Check("atomic-recovery-roundtrip-with-redo-tail",()=>{var s=Session();s.Change("0:a","first",2);s.Change("0:b","second",3);s.MoveHistory(false);string p=Path.Combine(folder,"session.json");s.Persist(p);var a=DocumentSession.Restore(p,s.SourceHash);Assert(a.Modified.Length==1&&a.CanRedo&&a.VerifiedRevision==-1,"Roundtrip mismatch");a.Register(new[]{Region("a"),Region("b"),Region("c",1)});a.MoveHistory(true);Assert(a.Modified.Length==2,"Recovered redo lost");});
Check("changed-source-refusal-preserves-recovery",()=>{string p=Path.Combine(folder,"session.json"),before=Wire.Hash(p);try{DocumentSession.Restore(p,new string('b',64));throw new Exception("Accepted stale source");}catch(IOException){}Assert(Wire.Hash(p)==before,"Recovery overwritten");});
Check("malformed-partial-recovery-retained",()=>{string p=Path.Combine(folder,"partial.json");File.WriteAllText(p,"{\"SourceHash\":");string hash=Wire.Hash(p);try{DocumentSession.Restore(p,new string('a',64));throw new Exception("Accepted partial recovery");}catch(System.Text.Json.JsonException){}Assert(Wire.Hash(p)==hash,"Partial recovery changed");});
Check("history-corruption-refused",()=>{var s=Session();s.Change("0:a","first",2);s.History[0]=s.History[0] with{After="different"};string p=Path.Combine(folder,"bad-history.json");s.Persist(p);try{DocumentSession.Restore(p,s.SourceHash);throw new Exception("Accepted contradictory history");}catch(IOException){}});
Check("oversize-recovery-keeps-previous-file-and-full-memory-draft",()=>{var s=Session();string p=Path.Combine(folder,"bounded.json");s.Persist(p);string hash=Wire.Hash(p);s.Change("0:a",new string('x',17_000_000),0);try{s.Persist(p);throw new Exception("Wrote oversized recovery");}catch(IOException){}Assert(Wire.Hash(p)==hash&&s.Regions["0:a"].Text.Length==17_000_000,"Oversize recovery/draft lost");});
Check("source-identity-and-recovered-compatibility",()=>{var s=Session();s.Change("0:a","draft",2);string identity=s.Regions["0:a"].Identity;s.Register(new[]{Region("a") with{Objects=[999]}});Assert(!s.Regions["0:a"].Compatible&&s.Regions["0:a"].Text=="draft"&&DocumentSession.Identity(s.Regions["0:a"].Original)==identity,"Mismatched discovery replaced source snapshot/draft");string p=Path.Combine(folder,"unresolved.json");s.Persist(p);Assert(DocumentSession.Restore(p,s.SourceHash).Regions["0:a"].Text=="draft","Unresolved draft not recoverable for inspection");});
if(args.Length>1)
{
 using var observations=System.Text.Json.JsonDocument.Parse(File.ReadAllText(args[1]));var element=observations.RootElement[0].GetProperty("lines")[0].GetProperty("region");var r=Wire.Read<Region>(element.GetRawText());
 Check("soft-wrap-keeps-exact-logical-text-and-spaces",()=>{string t=string.Join(" ",Enumerable.Repeat("Phase 3 letter",9));var p=PositionLayout.Plan(r,t);Assert(p.Safe&&p.Lines.Length==2&&string.Concat(p.Lines)==t&&!t.Contains('\n'),"Soft wrap changed text");string spaces=string.Join("  ",Enumerable.Repeat("Phase 3 letter",8));var q=PositionLayout.Plan(r,spaces);Assert(string.Concat(q.Lines)==spaces,"Adjacent spaces normalized");});
 Check("wrapped-baselines-and-new-line-font-advances",()=>{string t=string.Join(" ",Enumerable.Repeat("Phase 3 letter",9));var p=PositionLayout.Plan(r,t).Positioned!;Assert(p.Lines[0].Baseline==r.Baseline,"First baseline moved");foreach(var line in p.Lines.Skip(1)){Assert(line.Origins[0]==r.X&&line.Baseline-p.Lines[0].Baseline>=2*r.FontSize,"New baseline/anchor");for(int i=1;i<line.Text.Length;i++)Assert(Math.Abs(line.Origins[i]-line.Origins[i-1]-r.Advances[line.Text[i-1]-32])<.00001,"Obsolete source adjustment on new row");}});
 Check("wrapped-observations-immutable-and-vertical-refusal",()=>{string snapshot=Wire.Write(r);var p=PositionLayout.Plan(r,string.Join(" ",Enumerable.Repeat("Phase 3 letter",20)));Assert(!p.Safe&&p.ReasonCodes.Contains("POSITION_VERTICAL_OVERFLOW"),"Protected lower source ignored");Assert(Wire.Write(r)==snapshot,"Original observations overwritten");});
 Check("soft-wrap-caret-hit-all-logical-offsets",()=>{string t=string.Join(" ",Enumerable.Repeat("Phase 3 letter",9));for(int i=0;i<=t.Length;i++){var p=PositionLayout.Caret(r,t,i);Assert(PositionLayout.Hit(r,t,p.X+.001,p.Y+r.LineHeight/2).Index==i,"Caret logical offset differs");}});
 Check("hard-break-not-silently-converted",()=>{string t="Phase 3\nletter";var p=PositionLayout.Plan(r,t);Assert(!p.Safe&&p.Lines.Single()==t,"Hard break lost");});
 Check("position-insertion-preserves-surviving-pair-deltas",()=>{var p=PositionLayout.Plan(r,"Phasse 3 Office letter");Assert(p.Safe,"Insertion refused");var q=p.Positioned!;Assert(q.Origins[0]==r.X,"Anchor moved");for(int i=1;i<q.Origins.Length;i++)if(q.OriginalIndices[i-1]>=0&&q.OriginalIndices[i]==q.OriginalIndices[i-1]+1)Assert(Math.Abs(q.Origins[i]-q.Origins[i-1]-(r.Glyphs[q.OriginalIndices[i]].OriginX-r.Glyphs[q.OriginalIndices[i-1]].OriginX))<.00001,"Surviving pair changed");});
 Check("position-deletion-closes-new-join-with-font-advance",()=>{string t="Phase 3 Ofice letter";var q=PositionLayout.Plan(r,t).Positioned??throw new Exception("Deletion refused");for(int i=1;i<t.Length;i++)if(q.OriginalIndices[i]!=q.OriginalIndices[i-1]+1)Assert(Math.Abs(q.Origins[i]-q.Origins[i-1]-r.Advances[t[i-1]-32])<.00001,"Borrowed deleted-pair adjustment");});
 Check("position-fixed-legacy-substitution-still-fixed",()=>{var q=PositionLayout.Plan(r,"Phace 3 Office letter").Positioned!;Assert(q.Policy=="FixedOriginsEqualOrNarrowerSubstitution"&&q.Origins.SequenceEqual(r.Glyphs.Select(g=>g.OriginX)),"Legacy positions changed");});
 Check("position-source-observations-remain-immutable",()=>{string before=Wire.Write(r);PositionLayout.Plan(r,"Phase 3 letter");PositionLayout.Plan(r,"Phase 3 Office letter letter");Assert(Wire.Write(r)==before,"Source snapshot mutated");});
 Check("position-overflow-and-bounded-processing",()=>{Assert(!PositionLayout.Plan(r,r.OriginalText+new string('e',200)).Safe,"Overflow allowed");var p=PositionLayout.Plan(r,new string('e',100000));Assert(!p.Safe&&p.ReasonCodes.Contains("POSITION_LENGTH_LIMIT"),"Unbounded alignment");});
 Check("position-empty-line-keeps-source-ownership",()=>{var p=PositionLayout.Plan(r,"");Assert(p.Safe&&p.Positioned!.Origins.Length==0&&p.Positioned.DeletedOriginalIndices.Length==r.OriginalText.Length&&r.Positioned!.CoexistingWhitespace.Length>0,"Empty deletion/ownership");});
}
if(args.Length>2)
{
 using var evidence=System.Text.Json.JsonDocument.Parse(File.ReadAllText(args[2]));var group=Wire.Read<Region>(evidence.RootElement[2].GetProperty("sourceRegion").GetRawText());
 Check("group-exact-logical-text-without-soft-newlines",()=>{Assert(group.Paragraph!=null&&group.OriginalLines.Length==3&&group.OriginalText==string.Concat(group.OriginalLines)&&!group.OriginalText.Contains('\n'),"Soft rows became logical newlines");Assert(group.Glyphs.Select(g=>g.Index).SequenceEqual(Enumerable.Range(0,group.OriginalText.Length)),"Logical glyph offsets differ");});
 Check("group-source-plan-retains-observed-rows",()=>{var plan=PositionLayout.Plan(group,group.OriginalText);Assert(plan.Safe&&plan.Positioned!.Lines.Length==3,"Source rows lost");for(int i=0;i<group.Glyphs.Length;i++)Assert(plan.Positioned!.Origins[i]==group.Glyphs[i].OriginX,"Observed source origin changed");});
 Check("group-rewrap-pure-two-three-one",()=>{string before=Wire.Write(group);foreach(var (text,count) in new[]{(string.Join(" ",Enumerable.Repeat("Phase 3 letter",9)),2),(string.Join(" ",Enumerable.Repeat("Phase 3 letter",15)),3),("A separate letter.",1)}){var plan=PositionLayout.Plan(group,text);Assert(plan.Safe&&plan.Lines.Length==count&&string.Concat(plan.Lines)==text,"Group rewrap failed");}Assert(Wire.Write(group)==before,"Grouped source observations mutated");});
 Check("group-surviving-sequence-does-not-cross-source-soft-boundary",()=>{var map=Enumerable.Range(0,group.OriginalText.Length).ToArray();int boundary=group.Positioned!.SourceLines[1].Start;Assert(PositionLayout.SourceSequence(group,map,0,2)&&!PositionLayout.SourceSequence(group,map,boundary-1,boundary),"Obsolete pair exception across source rows");});
 Check("group-identity-bound-to-new-source-and-complete-observations",()=>{string hash=group.SourceIdentity;Assert((group with{FontFile="irrelevant-temporary-path.ttf"}).SourceIdentity==hash,"Temporary path affects identity");Assert((group with{SourceHash=new string('f',64)}).SourceIdentity!=hash,"Source fingerprint omitted");Assert((group with{Paragraph=group.Paragraph! with{PayloadHash=new string('e',64)}}).SourceIdentity!=hash,"Validated payload omitted");});
 Check("group-recovery-retains-source-rows-logical-text-and-chronology",()=>{var session=new DocumentSession{Source="group.pdf",SourceHash=group.SourceHash};session.Register([group]);string key=DocumentSession.Key(group.Page,group.Id);session.Change(key,"A separate letter.",3);string path=Path.Combine(folder,"group-session.json");session.Persist(path);var restored=DocumentSession.Restore(path,group.SourceHash);Assert(restored.Regions[key].Original.OriginalText==group.OriginalText&&restored.Regions[key].Original.Positioned!.SourceLines.Length==3&&restored.History.Count==1&&restored.Regions[key].Text=="A separate letter.","Group recovery changed meaning");bool blocked=false;try{DocumentSession.Restore(path,new string('b',64));}catch{blocked=true;}Assert(blocked,"Foreign source recovery attached");});
 Check("group-recovery-keeps-repeated-spaces-exact",()=>{var session=new DocumentSession{Source="group.pdf",SourceHash=group.SourceHash};session.Register([group]);string key=DocumentSession.Key(group.Page,group.Id),text=group.OriginalText.Replace("Phase 3","Phase  3");session.Change(key,text,5);string path=Path.Combine(folder,"group-spaces-session.json");session.Persist(path);var restored=DocumentSession.Restore(path,group.SourceHash);Assert(restored.Regions[key].Text==text&&restored.Regions[key].Text.Contains("  "),"Meaningful spaces normalised in recovery");});
}
File.WriteAllText(Path.Combine(folder,"model-tests.json"),Wire.Write(new{tests=rows.Count,failures,rows}));Console.WriteLine($"Session model: {rows.Count-failures}/{rows.Count} passed");Environment.ExitCode=failures==0?0:1;
